import { describe, expect, it } from "vitest";
import { checkMoneroWords, moneroWordFor, suggestWords } from "../src/seedcheck";

// Throwaway seeds generated by the Monero wallet engine (monero-ts 0.11.20); never funded.
const SEEDS = [
  "hashing boss weavers adopt bumper orders hatchet slackens rafts inundate gills dialect itches bakery dotted july ceiling tycoon buckets woven skulls lyrics inline keyboard woven",
  "gusts affair gutter tissue evenings inline imagine basin equip succeed cement dormant mural lively invoke debut afield richly peculiar five optical magically vogue abbey lively",
  "dehydrate afar moment vague hippo dosage sober gimmick amused jazz knowledge nugget autumn utopia moon diode huge eccentric metro template debut apricot tiers tufts utopia",
  "tasked haggled shuffled gutter toaster boxes knee ditch betting situated gumball ostrich amply corrode igloo cake ruby ozone doctor boxes nagged peeled second sovereign ruby",
];
const SPANISH = "fruta folio exigir guiso fábula choque bola comida burla pulga leña pluma mujer nota cromo empeño beso grupo edad amistad arduo lesión legión lingote arduo";

const words = (s: string) => s.split(" ");

describe("checkMoneroWords", () => {
  it("accepts real 25-word seeds (the checksum matches)", () => {
    for (const s of SEEDS) expect(checkMoneroWords(s)).toEqual({ kind: "ok" });
  });

  it("finds the missing 25th word from 24 words", () => {
    for (const s of SEEDS) {
      const w = words(s);
      expect(checkMoneroWords(w.slice(0, 24).join(" "))).toEqual({ kind: "missing-checksum", word: w[24] });
    }
  });

  it("flags a changed word through the checksum", () => {
    const w = words(SEEDS[0]!);
    // Swap two different words: every word is still valid, but the order changed.
    [w[0], w[1]] = [w[1]!, w[0]!];
    expect(checkMoneroWords(w.join(" ")).kind).toBe("bad-checksum");
  });

  it("names unknown words with likely corrections", () => {
    const w = words(SEEDS[1]!);
    w[3] = "tisue"; // "tis" is still a valid prefix, so Monero reads it as "tissue": not an error
    w[6] = "imagne"; // prefix "ima" is fine too
    w[9] = "sxcceed"; // prefix "sxc" matches nothing
    const r = checkMoneroWords(w.join(" "));
    expect(r.kind).toBe("unknown-words");
    if (r.kind === "unknown-words") {
      expect(r.unknown.map((u) => u.position)).toEqual([10]);
      expect(r.unknown[0]!.suggestions).toContain("succeed");
    }
  });

  it("reads words by their first three letters, as Monero does", () => {
    expect(moneroWordFor("hashin")).toBe("hashing");
    expect(moneroWordFor("HAS")).toBe("hashing");
    expect(moneroWordFor("zzz")).toBeNull();
  });

  it("stays quiet for other lengths and other languages", () => {
    expect(checkMoneroWords("one two three")).toEqual({ kind: "skip" });
    expect(checkMoneroWords(words(SEEDS[0]!).slice(0, 13).join(" "))).toEqual({ kind: "skip" });
    expect(checkMoneroWords(SPANISH)).toEqual({ kind: "skip" });
  });

  it("suggests close words", () => {
    expect(suggestWords("abbbey")).toContain("abbey");
    expect(suggestWords("qqqqqqqq")).toEqual([]);
  });
});
